import UIKit
import QuartzCore
import CFrustFFI

// Generated by `frust create`. Hosts native UIKit
// sibling views alongside the Frust render surface, driven by the
// per-frame command channel `frust_platform_view_commands_json` exposes.
// The iOS mirror of Android's `dev.frust.FrustViewHost`.
//
// Lifecycle: `FrustViewController` owns one host, constructed once
// `frust_init` has a handle, and calls `poll(handle:)` from its
// `CADisplayLink` callback right after `frust_render_frame`. A poll reads
// the JSON backlog accumulated since the last acknowledged generation,
// applies every create/reposition/dispose command inside a single
// `CATransaction` (implicit animations disabled — a reposition must snap,
// not tween), and records the new generation as acknowledged.
//
// Coordinate boundary: rects arrive in PHYSICAL pixels (the physical-at-FFI
// convention shared with Android). UIKit lays out in logical points, so
// every rect is divided by the container's `contentScaleFactor` at the
// boundary (see [pointsRect]).
//
// Z-order: in translucent (Mode B) apps the native views sit BELOW the
// Frust surface (which is non-opaque, so they show through); in opaque
// (Mode A) apps they sit ABOVE it. The choice is fixed per-app by the
// controller's `translucentSurface` const in v1 (per-slot z policy is
// future work).
//
// Overlay surfaces (`FRUST_OVERLAYS`, default off, Mode A only): the differ
// cuts each frame's commands at its visible slots and announces one overlay
// per cut (`overlay` / `disposeOverlay` ops). For each, the host stacks an
// input-transparent, non-opaque `CAMetalLayer` view (`FrustOverlayView`)
// DIRECTLY ABOVE that slot's wrapper, covering the op's rect (the whole
// surface), and hands its layer to Rust (`frust_overlay_attach`); Frust draws
// the commands painted after that native view — and before the next one —
// onto it, so its paint lands above the view and below any later slot. With
// overlays on, a new wrapper goes above every hosted view (wrappers then stack
// in creation order, which is paint order for a newly shown slot) instead of
// directly above the Frust surface. A layer is detached
// (`frust_overlay_detach`, which drops its surface) before its view is
// released. Mode B ignores the ops: the translucent surface already composites
// above its native views.

/// An overlay surface's view: a non-opaque `CAMetalLayer` Frust presents
/// into, invisible to touches (`hitTest` answers nil and user interaction is
/// off), so the native view under it and the Frust surface keep today's
/// input rules.
final class FrustOverlayView: UIView {
    override class var layerClass: AnyClass { CAMetalLayer.self }

    var metalLayer: CAMetalLayer { layer as! CAMetalLayer }

    override init(frame: CGRect) {
        super.init(frame: frame)
        isOpaque = false
        backgroundColor = .clear
        isUserInteractionEnabled = false
        metalLayer.isOpaque = false
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    override func hitTest(_ point: CGPoint, with event: UIEvent?) -> UIView? { nil }
}

final class FrustViewHost {
    /// A live slot: the `wrapper` is the sibling added to the hierarchy (it
    /// carries position + clip), `content` is the factory-produced view
    /// inside it, and `factory` is retained for its `updateParams`/
    /// `disposeView` hooks.
    private struct Slot {
        let wrapper: UIView
        let content: UIView
        let factory: FrustPlatformViewFactory
        /// Mode B input forwarding: whether a touch
        /// landing inside this slot's rect should fall through the Frust
        /// surface to [content] (see `FrustView.hitTest`).
        let interactive: Bool
        /// The z-shield list (logical points, same space as [wrapper]'s
        /// frame): regions where Frust content drawn over the slot keeps
        /// winning input. Replaced wholesale by every `update` command.
        var shields: [CGRect]
    }

    /// Mode B input forwarding: whether a touch at
    /// `point` (in the shared superview's coordinate space — the Frust
    /// surface fills it at origin zero, so `FrustView`-local and superview
    /// space coincide) belongs to an interactive hosted view. `true` ⇒ the
    /// Frust surface's `hitTest` returns nil and UIKit routes the whole
    /// gesture to the sibling natively.
    func interactiveSlotContains(_ point: CGPoint) -> Bool {
        for slot in slots.values {
            guard slot.interactive, !slot.wrapper.isHidden else { continue }
            guard slot.wrapper.frame.contains(point) else { continue }
            if slot.shields.contains(where: { $0.contains(point) }) { continue }
            return true
        }
        return false
    }

    /// The Frust surface view (a `FrustView`); hosted wrappers are inserted
    /// as its siblings in the same superview, so this is `unowned` — the
    /// controller outlives the host and owns the view.
    private unowned let containerView: UIView
    /// `true` when the app requested a translucent surface (Mode B): hosted
    /// views go BELOW the Frust surface. `false` (Mode A): ABOVE.
    private let translucent: Bool

    private var slots: [UInt64: Slot] = [:]
    /// Slots whose factory failed to resolve — remembered so a repeated
    /// `create` for the same id doesn't re-log every frame. Never crashes
    /// the frame loop (a bad `viewType` is an app bug, not a fatal one).
    private var deadSlots: Set<UInt64> = []
    /// Resolved factories, cached per `viewType` (`NSClassFromString` +
    /// instantiation is done once per type, not per slot).
    private var factoryCache: [String: FrustPlatformViewFactory] = [:]

    /// The last generation whose command batch has been applied. Passed back
    /// into `frust_platform_view_commands_json` so the Rust side can return
    /// the cheap null "no change" fast path when nothing new has happened.
    private(set) var ackedGeneration: UInt64 = 0

    /// A live overlay: its view (hosting the layer Rust draws into), the slot
    /// it sits directly above, and the geometry last handed to Rust.
    private struct Overlay {
        let view: FrustOverlayView
        let aboveSlot: UInt64
        var frame: CGRect
        var pixelWidth: UInt32
        var pixelHeight: UInt32
    }

    /// Whether this host builds overlay views for the `overlay` ops — the
    /// switch is on (`frust_overlay_mode`) and the surface is opaque (Mode B
    /// acknowledges and ignores them).
    private let overlaysEnabled: Bool
    /// Whether overlay layers present inside the display-link tick's
    /// `CATransaction`, like the Frust surface's own layer under present-sync.
    private let overlaysPresentWithTransaction: Bool
    /// The live overlays by the differ's overlay id.
    private var overlays: [UInt64: Overlay] = [:]
    /// Overlays whose slot had no wrapper (a dead slot), remembered so the
    /// skip is logged once.
    private var orphanOverlays: Set<UInt64> = []
    /// The handle of the poll in progress — the overlay calls need it.
    private var handle: UnsafeMutableRawPointer?

    init(
        containerView: UIView, translucent: Bool, handle: UnsafeMutableRawPointer? = nil,
        presentsWithTransaction: Bool = false
    ) {
        self.containerView = containerView
        self.translucent = translucent
        self.handle = handle
        self.overlaysPresentWithTransaction = presentsWithTransaction
        let requested = handle.map { frust_overlay_mode($0) > 0 } ?? false
        if requested && translucent {
            NSLog("frust-overlay: overlays are Mode A only; a translucent surface ignores them")
        }
        self.overlaysEnabled = requested && !translucent
        if self.overlaysEnabled {
            NSLog("frust-overlay: overlay views on (Mode A)")
        }
    }

    /// Pull and apply this frame's platform-view command batch. Cheap when
    /// idle: a null return (nothing changed since [ackedGeneration]) is the
    /// common case and does no work. Called on the main thread (the
    /// `CADisplayLink` callback), so all UIKit mutation below is main-thread.
    func poll(handle: UnsafeMutableRawPointer) {
        self.handle = handle
        guard let raw = frust_platform_view_commands_json(handle, ackedGeneration) else { return }
        defer { frust_string_free(raw) }
        let data = Data(bytes: raw, count: strlen(raw))
        guard
            let root = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
            let generation = (root["generation"] as? NSNumber)?.uint64Value
        else { return }
        let commands = (root["commands"] as? [[String: Any]]) ?? []

        // One transaction for the whole batch, with implicit animations
        // disabled: a reposition snaps to its new frame rather than tweening
        // (frust owns all motion; a UIKit auto-animation would fight it).
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        for command in commands {
            apply(command)
        }
        CATransaction.commit()

        ackedGeneration = generation
    }

    /// Apply one command.
    private func apply(_ command: [String: Any]) {
        guard let op = command["op"] as? String else { return }
        switch op {
        case "overlay":
            applyOverlay(command)
            return
        case "disposeOverlay":
            applyDisposeOverlay(command)
            return
        default:
            break
        }
        guard let slotId = (command["slot"] as? NSNumber)?.uint64Value else { return }
        switch op {
        case "create":
            applyCreate(slotId: slotId, command: command)
        case "update":
            applyUpdate(slotId: slotId, command: command)
        case "updateParams":
            applyUpdateParams(slotId: slotId, command: command)
        case "dispose":
            applyDispose(slotId: slotId)
        default:
            break  // Unknown op (forward-compat): ignore rather than crash.
        }
    }

    // MARK: - Overlay surfaces

    /// Create or re-place one overlay: a new one is stacked directly above its
    /// slot's wrapper and its layer handed to Rust; a known one adopts a
    /// changed rect, re-announcing the layer at its new drawable size (Rust
    /// resizes the surface and requests a frame). Ignored in Mode B or with
    /// the switch off — the poll still acknowledges it.
    private func applyOverlay(_ command: [String: Any]) {
        guard overlaysEnabled, let handle,
            let overlayId = (command["overlay"] as? NSNumber)?.uint64Value,
            let aboveSlot = (command["aboveSlot"] as? NSNumber)?.uint64Value,
            let pixels = physicalRect(command["rect"])
        else { return }
        let scale = containerView.contentScaleFactor
        guard scale > 0 else { return }
        let frame = CGRect(
            x: pixels.origin.x / scale, y: pixels.origin.y / scale,
            width: pixels.width / scale, height: pixels.height / scale)
        let width = UInt32(max(pixels.width.rounded(), 1))
        let height = UInt32(max(pixels.height.rounded(), 1))

        if var overlay = overlays[overlayId] {
            guard overlay.frame != frame || overlay.pixelWidth != width
                || overlay.pixelHeight != height
            else { return }
            place(overlay.view, frame: frame, width: width, height: height)
            overlay.frame = frame
            overlay.pixelWidth = width
            overlay.pixelHeight = height
            overlays[overlayId] = overlay
            frust_overlay_attach(
                handle, overlayId, Unmanaged.passUnretained(overlay.view.metalLayer).toOpaque(),
                width, height)
            return
        }

        guard let slot = slots[aboveSlot], let superview = containerView.superview else {
            // No wrapper to stack above (a dead slot): the content stays on the
            // Frust surface, under where the view would be.
            if orphanOverlays.insert(overlayId).inserted {
                NSLog("frust-overlay: overlay \(overlayId) has no slot \(aboveSlot) to sit above; skipped")
            }
            return
        }
        let view = FrustOverlayView(frame: frame)
        view.metalLayer.presentsWithTransaction = overlaysPresentWithTransaction
        place(view, frame: frame, width: width, height: height)
        // Directly above its own slot: below every later-painted slot, so
        // frust content painted between two native views stays between them.
        superview.insertSubview(view, aboveSubview: slot.wrapper)
        overlays[overlayId] = Overlay(
            view: view, aboveSlot: aboveSlot, frame: frame, pixelWidth: width,
            pixelHeight: height)
        frust_overlay_attach(
            handle, overlayId, Unmanaged.passUnretained(view.metalLayer).toOpaque(), width, height)
        NSLog("frust-overlay: overlay \(overlayId) view above slot \(aboveSlot) (\(width)x\(height) px)")
    }

    /// Tear one overlay down: Rust drops its surface (and any frame of it
    /// waiting to be presented) BEFORE the view and its layer go away.
    private func applyDisposeOverlay(_ command: [String: Any]) {
        guard let overlayId = (command["overlay"] as? NSNumber)?.uint64Value else { return }
        orphanOverlays.remove(overlayId)
        guard let overlay = overlays.removeValue(forKey: overlayId) else { return }
        if let handle { frust_overlay_detach(handle, overlayId) }
        overlay.view.removeFromSuperview()
        NSLog("frust-overlay: overlay \(overlayId) view removed")
    }

    /// Size an overlay's view and drawable.
    private func place(_ view: FrustOverlayView, frame: CGRect, width: UInt32, height: UInt32) {
        view.frame = frame
        view.contentScaleFactor = containerView.contentScaleFactor
        view.metalLayer.contentsScale = containerView.contentScaleFactor
        view.metalLayer.drawableSize = CGSize(width: Int(width), height: Int(height))
    }

    /// The view a newly created wrapper goes directly above with overlays on:
    /// the topmost hosted wrapper or overlay view, else the Frust surface.
    private func topmostHostedView() -> UIView {
        guard let superview = containerView.superview else { return containerView }
        let hosted = Set(
            slots.values.map { ObjectIdentifier($0.wrapper) }
                + overlays.values.map { ObjectIdentifier($0.view) })
        return superview.subviews.last { hosted.contains(ObjectIdentifier($0)) } ?? containerView
    }

    private func applyCreate(slotId: UInt64, command: [String: Any]) {
        guard slots[slotId] == nil else { return }
        guard let viewType = command["viewType"] as? String else { return }
        let params = (command["params"] as? String) ?? ""

        guard let factory = resolveFactory(viewType) else {
            // Dead slot: log once, never crash the frame loop.
            if deadSlots.insert(slotId).inserted {
                NSLog("Frust: no platform-view factory for `\(viewType)` (slot \(slotId)) — skipping")
            }
            return
        }

        let content = factory.createView(paramsJson: params)
        let wrapper = UIView()
        wrapper.isHidden = true  // Shown by the first `update` with visible=true.
        wrapper.addSubview(content)

        // Mode B (translucent): behind the Frust surface. Mode A: in front —
        // with overlays on, above every hosted view (and so above the overlay
        // of each slot painted before it), otherwise directly above the
        // surface as before.
        if translucent {
            containerView.superview?.insertSubview(wrapper, belowSubview: containerView)
        } else if overlaysEnabled {
            containerView.superview?.insertSubview(wrapper, aboveSubview: topmostHostedView())
        } else {
            containerView.superview?.insertSubview(wrapper, aboveSubview: containerView)
        }
        slots[slotId] = Slot(
            wrapper: wrapper,
            content: content,
            factory: factory,
            interactive: (command["interactive"] as? Bool) ?? false,
            shields: []
        )
    }

    private func applyUpdate(slotId: UInt64, command: [String: Any]) {
        guard let slot = slots[slotId] else { return }
        let scale = containerView.contentScaleFactor
        guard let rect = pointsRect(command["rect"], scale: scale) else { return }
        let clip = pointsRect(command["clip"], scale: scale)
        let visible = (command["visible"] as? Bool) ?? true

        // The wrapper carries the clip window; the content is positioned
        // relative to it. With no clip (or a clip that fully contains the
        // rect) the wrapper IS the rect and no masking is needed — masking
        // only when clip < rect avoids a gratuitous offscreen clip pass.
        if let clip, clip != rect {
            slot.wrapper.frame = clip
            slot.wrapper.layer.masksToBounds = true
            slot.content.frame = CGRect(
                x: rect.origin.x - clip.origin.x,
                y: rect.origin.y - clip.origin.y,
                width: rect.width,
                height: rect.height
            )
        } else {
            slot.wrapper.frame = rect
            slot.wrapper.layer.masksToBounds = false
            slot.content.frame = slot.wrapper.bounds
        }
        slot.wrapper.isHidden = !visible

        // The z-shield list rides every update in the same physical-px space
        // as `rect` — converted to points and replaced wholesale.
        let shieldArrays = (command["shields"] as? [Any]) ?? []
        slots[slotId]?.shields = shieldArrays.compactMap { pointsRect($0, scale: scale) }
    }

    private func applyUpdateParams(slotId: UInt64, command: [String: Any]) {
        guard let slot = slots[slotId], let params = command["params"] as? String else { return }
        slot.factory.updateParams?(slot.content, paramsJson: params)
    }

    private func applyDispose(slotId: UInt64) {
        deadSlots.remove(slotId)
        guard let slot = slots.removeValue(forKey: slotId) else { return }
        slot.factory.disposeView?(slot.content)
        slot.wrapper.removeFromSuperview()
    }

    /// Resolve (and cache) the factory for a `viewType`. `viewType` is the
    /// ObjC runtime class name of an `@objc(...)`-annotated `NSObject`
    /// factory (see `FrustPlatformViewFactory`'s doc). A failure returns
    /// `nil` — the caller marks the slot dead, never crashes.
    ///
    /// **Check order is part of the contract, not an implementation
    /// detail:** `NSClassFromString` resolves the class object, then
    /// `class_conformsToProtocol` verifies `FrustPlatformViewFactory`
    /// conformance on the *class object* — BOTH BEFORE `init()` ever runs.
    /// iOS has no package-prefix convention (bare `@objc` names are the
    /// contract — `docs/CODE_STANDARDS.md`'s Naming Conventions), so
    /// conformance-before-init is the whole fix: instantiating an
    /// arbitrary attacker-influenced class name before checking what it is
    /// lets a no-arg `init()`'s side effects run unconditionally.
    private func resolveFactory(_ viewType: String) -> FrustPlatformViewFactory? {
        if let cached = factoryCache[viewType] {
            return cached
        }
        guard
            let cls = NSClassFromString(viewType) as? NSObject.Type,
            class_conformsToProtocol(cls, FrustPlatformViewFactory.self)
        else {
            return nil
        }
        guard let factory = cls.init() as? FrustPlatformViewFactory else {
            return nil
        }
        factoryCache[viewType] = factory
        return factory
    }

    /// A `[x, y, w, h]` PHYSICAL-pixel JSON array as-is (no scale), `nil` for a
    /// missing or malformed value.
    private func physicalRect(_ value: Any?) -> CGRect? {
        guard let array = value as? [Any], array.count == 4 else { return nil }
        let numbers = array.compactMap { ($0 as? NSNumber)?.doubleValue }
        guard numbers.count == 4 else { return nil }
        return CGRect(x: numbers[0], y: numbers[1], width: numbers[2], height: numbers[3])
    }

    /// Convert a `[x, y, w, h]` PHYSICAL-pixel JSON array into a logical-point
    /// `CGRect` (dividing by the display scale — the physical-at-FFI boundary).
    /// `nil` for a missing/`null`/malformed value (e.g. a `null` clip).
    private func pointsRect(_ value: Any?, scale: CGFloat) -> CGRect? {
        guard let array = value as? [Any], array.count == 4 else { return nil }
        let numbers = array.compactMap { ($0 as? NSNumber)?.doubleValue }
        guard numbers.count == 4, scale > 0 else { return nil }
        return CGRect(
            x: numbers[0] / scale,
            y: numbers[1] / scale,
            width: numbers[2] / scale,
            height: numbers[3] / scale
        )
    }
}

#if DEBUG
    /// A debug-only factory shipped with the template so a generated app can
    /// exercise the platform-view path end-to-end without writing a factory:
    /// set a `platform_view` widget's `viewType` to `"FrustTestLabelFactory"`.
    /// The label self-updates a counter on its own timer — independent of the
    /// Frust frame loop — which is how a device trace check proves a hosted
    /// view redraws with ZERO frust frames. Guarded by `#if DEBUG` and kept in
    /// this file (not a third pbxproj source) so a release build drops it.
    @objc(FrustTestLabelFactory)
    final class FrustTestLabelFactory: NSObject, FrustPlatformViewFactory {
        func createView(paramsJson: String) -> UIView {
            return FrustTestLabel(paramsJson: paramsJson)
        }
    }

    /// A `UILabel` that redraws itself every 0.5s off a `Timer` — no Frust
    /// frame involved. Displays its creation `paramsJson` plus a live counter.
    private final class FrustTestLabel: UILabel {
        private let paramsJson: String
        private var counter = 0
        private var timer: Timer?

        init(paramsJson: String) {
            self.paramsJson = paramsJson
            super.init(frame: .zero)
            numberOfLines = 0
            textAlignment = .center
            textColor = .white
            backgroundColor = UIColor.systemBlue.withAlphaComponent(0.6)
            render()
            let timer = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in
                guard let self else { return }
                self.counter += 1
                self.render()
            }
            RunLoop.main.add(timer, forMode: .common)
            self.timer = timer
        }

        required init?(coder: NSCoder) {
            fatalError("init(coder:) has not been implemented")
        }

        private func render() {
            text = "\(paramsJson)\n#\(counter)"
        }

        deinit {
            timer?.invalidate()
        }
    }
#endif
